const quotes = items[0].json;
const videoFiles = items[1].json;
const musicFiles = items[2].json;

// Filter quotes that are not yet processed
const pendingQuotes = quotes.filter(q => !q.CreateStatus);

// Select a random quote
const selectedQuote = pendingQuotes[Math.floor(Math.random() * pendingQuotes.length)];

// Select random video and music
const selectedVideo = videoFiles[Math.floor(Math.random() * videoFiles.length)];
const selectedMusic = musicFiles[Math.floor(Math.random() * musicFiles.length)];

// FFmpeg command to overlay text on video
const ffmpegCommand = `ffmpeg -i ${selectedVideo.webContentLink} -vf "drawtext=text='${selectedQuote.Quote} - ${selectedQuote.Author}':fontfile=/path/to/Kanit.ttf:fontsize=24:fontcolor=white:x=(w-text_w)/2:y=(h-text_h)/2" -i ${selectedMusic.webContentLink} -shortest -y output.mp4`;

// Execute FFmpeg command
const execSync = require('child_process').execSync;
execSync(ffmpegCommand);

return [{ json: { quote: selectedQuote, outputFile: 'output.mp4' } }];
